import { useState, useEffect, useRef, useCallback } from 'react';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { createBroadcastChannel, removeChannel } from './realtime';
import { generateRoomCode, channelName, generateRoomName } from './roomCode';
import type { Player, PlayerRole, RoomState, MultiplayerEvent } from './types';

function generatePlayerId(): string {
  return Math.random().toString(36).slice(2, 8);
}

interface UseMultiplayerOptions {
  gameId: string;
  playerName: string;
  onEvent: (event: MultiplayerEvent) => void;
}

interface UseMultiplayerReturn {
  room: RoomState | null;
  createRoom: () => { code: string; roomName: string };
  joinRoom: (code: string) => void;
  sendEvent: (event: MultiplayerEvent) => void;
  leaveRoom: () => void;
  /** @deprecated Use addPlayer for N-player games. Kept for TicTacToe compat. */
  setConnected: (opponentName: string) => void;
  addPlayer: (player: Player) => void;
  removePlayer: (playerId: string) => void;
  setPlayers: (players: Player[]) => void;
  error: string | null;
}

export function useMultiplayer({
  gameId,
  playerName,
  onEvent,
}: UseMultiplayerOptions): UseMultiplayerReturn {
  const [room, setRoom] = useState<RoomState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const channelRef = useRef<RealtimeChannel | null>(null);
  const onEventRef = useRef(onEvent);
  onEventRef.current = onEvent;
  const playerNameRef = useRef(playerName);
  playerNameRef.current = playerName;
  const playerIdRef = useRef(generatePlayerId());

  const subscribe = useCallback(
    (roomCode: string, role: PlayerRole) => {
      const ch = createBroadcastChannel(channelName(gameId, roomCode));

      ch.on('broadcast', { event: 'mp' }, ({ payload }) => {
        onEventRef.current(payload as MultiplayerEvent);
      });

      ch.subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          channelRef.current = ch;
          if (role === 'guest') {
            ch.send({
              type: 'broadcast',
              event: 'mp',
              payload: {
                type: 'guest-joined',
                name: playerNameRef.current,
                playerId: playerIdRef.current,
              },
            });
          }
        } else if (status === 'CHANNEL_ERROR') {
          setError('Connection failed. Check your internet and try again.');
        }
      });

      return ch;
    },
    [gameId],
  );

  const createRoom = useCallback((): { code: string; roomName: string } => {
    playerIdRef.current = generatePlayerId();
    const code = generateRoomCode();
    const name = generateRoomName(gameId, playerNameRef.current);
    subscribe(code, 'host');
    const hostPlayer: Player = {
      id: playerIdRef.current,
      name: playerNameRef.current,
      isHost: true,
    };
    setRoom({
      code,
      roomName: name,
      role: 'host',
      playerId: playerIdRef.current,
      playerName: playerNameRef.current,
      players: [hostPlayer],
      opponentName: null,
      connected: false,
    });
    setError(null);
    return { code, roomName: name };
  }, [subscribe, gameId]);

  const joinRoom = useCallback(
    (code: string): void => {
      playerIdRef.current = generatePlayerId();
      const normalized = code.toUpperCase().trim();
      subscribe(normalized, 'guest');
      const me: Player = {
        id: playerIdRef.current,
        name: playerNameRef.current,
        isHost: false,
      };
      setRoom({
        code: normalized,
        roomName: '',
        role: 'guest',
        playerId: playerIdRef.current,
        playerName: playerNameRef.current,
        players: [me],
        opponentName: null,
        connected: false,
      });
      setError(null);
    },
    [subscribe],
  );

  const sendEvent = useCallback((event: MultiplayerEvent): void => {
    channelRef.current?.send({
      type: 'broadcast',
      event: 'mp',
      payload: event,
    });
  }, []);

  const leaveRoom = useCallback((): void => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'mp',
        payload: {
          type: 'player-left',
          playerId: playerIdRef.current,
          name: playerNameRef.current,
        },
      });
      removeChannel(channelRef.current);
      channelRef.current = null;
    }
    setRoom(null);
    setError(null);
  }, []);

  /** Compat method for 2-player games */
  const setConnected = useCallback((opponentName: string) => {
    setRoom((prev) =>
      prev ? { ...prev, opponentName, connected: true } : prev,
    );
  }, []);

  const addPlayer = useCallback((player: Player) => {
    setRoom((prev) => {
      if (!prev) return prev;
      if (prev.players.some((p) => p.id === player.id)) return prev;
      const players = [...prev.players, player];
      const firstOpponent = players.find((p) => p.id !== prev.playerId);
      return {
        ...prev,
        players,
        opponentName: firstOpponent?.name ?? null,
        connected: true,
      };
    });
  }, []);

  const removePlayer = useCallback((playerId: string) => {
    setRoom((prev) => {
      if (!prev) return prev;
      const players = prev.players.filter((p) => p.id !== playerId);
      const firstOpponent = players.find((p) => p.id !== prev.playerId);
      return {
        ...prev,
        players,
        opponentName: firstOpponent?.name ?? null,
        connected: players.length > 1,
      };
    });
  }, []);

  const setPlayers = useCallback((players: Player[]) => {
    setRoom((prev) => {
      if (!prev) return prev;
      const firstOpponent = players.find((p) => p.id !== prev.playerId);
      return {
        ...prev,
        players,
        opponentName: firstOpponent?.name ?? null,
        connected: players.length > 1,
      };
    });
  }, []);

  useEffect(() => {
    return () => {
      if (channelRef.current) {
        channelRef.current.send({
          type: 'broadcast',
          event: 'mp',
          payload: {
            type: 'player-left',
            playerId: playerIdRef.current,
            name: playerNameRef.current,
          },
        });
        removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, []);

  return {
    room,
    createRoom,
    joinRoom,
    sendEvent,
    leaveRoom,
    setConnected,
    addPlayer,
    removePlayer,
    setPlayers,
    error,
  };
}
