// ─── Map generation ─────────────────────────────────────────────────────────

const SPAWN_ZONES: [number, number][] = [
  [0, 0], [0, 1], [1, 0],
  [0, COLS - 1], [0, COLS - 2], [1, COLS - 1],
  [ROWS - 1, 0], [ROWS - 1, 1], [ROWS - 2, 0],
  [ROWS - 1, COLS - 1], [ROWS - 1, COLS - 2], [ROWS - 2, COLS - 1],
];

function isSpawnZone(r: number, c: number): boolean {
  return SPAWN_ZONES.some(([sr, sc]) => sr === r && sc === c);
}

function generateGrid(): number[][] {
  const grid: number[][] = [];
  for (let r = 0; r < ROWS; r++) {
    grid[r] = [];
    for (let c = 0; c < COLS; c++) {
      if (r % 2 === 0 && c % 2 === 0 && r > 0 && r < ROWS - 1 && c > 0 && c < COLS - 1) {
        grid[r][c] = WALL;
      } else if (isSpawnZone(r, c)) {
        grid[r][c] = EMPTY;
      } else {
        grid[r][c] = Math.random() < BLOCK_FILL ? BLOCK : EMPTY;
      }
    }
  }
  return grid;
}

// ─── Game logic helpers ─────────────────────────────────────────────────────

function randomPowerUp(): PowerUpType {
  const total = POWERUP_WEIGHTS.reduce((a, b) => a + b, 0);
  let r = Math.random() * total;
  for (let i = 0; i < POWERUP_TYPES.length; i++) {
    r -= POWERUP_WEIGHTS[i];
    if (r <= 0) return POWERUP_TYPES[i];
  }
  return 'fire';
}

function canPass(grid: number[][], r: number, c: number, ghost: boolean): boolean {
  if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
  if (grid[r][c] === WALL) return false;
  if (grid[r][c] === BLOCK && !ghost) return false;
  return true;
}

function getDangerCells(bombs: Bomb[], grid: number[][]): Set<string> {
  const danger = new Set<string>();
  for (const bomb of bombs) {
    if (bomb.detonated) continue;
    danger.add(`${bomb.row},${bomb.col}`);
    for (const [dr, dc] of DIRS) {
      for (let i = 1; i <= bomb.range; i++) {
        const nr = bomb.row + dr * i;
        const nc = bomb.col + dc * i;
        if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS || grid[nr][nc] === WALL) break;
        danger.add(`${nr},${nc}`);
        if (grid[nr][nc] === BLOCK) break;
      }
    }
  }
  return danger;
}

function bfsFind(
  grid: number[][],
  bombs: Bomb[],
  startR: number,
  startC: number,
  target: (r: number, c: number) => boolean,
  ghost: boolean,
): [number, number] | null {
  const visited = new Set<string>();
  const queue: { r: number; c: number; firstR: number; firstC: number }[] = [];
  visited.add(`${startR},${startC}`);
  const bombCells = new Set(bombs.filter((b) => !b.detonated).map((b) => `${b.row},${b.col}`));

  for (const [dr, dc] of DIRS) {
    const nr = startR + dr;
    const nc = startC + dc;
    if (canPass(grid, nr, nc, ghost) && !bombCells.has(`${nr},${nc}`)) {
      if (target(nr, nc)) return [nr, nc];
      visited.add(`${nr},${nc}`);
      queue.push({ r: nr, c: nc, firstR: nr, firstC: nc });
    }
  }

  while (queue.length > 0) {
    const { r, c, firstR, firstC } = queue.shift()!;
    for (const [dr, dc] of DIRS) {
      const nr = r + dr;
      const nc = c + dc;
      const key = `${nr},${nc}`;
      if (!visited.has(key) && canPass(grid, nr, nc, ghost) && !bombCells.has(key)) {
        if (target(nr, nc)) return [firstR, firstC];
        visited.add(key);
        queue.push({ r: nr, c: nc, firstR, firstC });
      }
    }
  }
  return null;
}

// ─── AI logic ───────────────────────────────────────────────────────────────

function dirFromDelta(dr: number, dc: number): Dir {
  if (dr === -1) return 'up';
  if (dr === 1) return 'down';
  if (dc === -1) return 'left';
  if (dc === 1) return 'right';
  return null;
}

/** Find the nearest alive enemy */
function findNearestEnemy(player: Player, playerIdx: number, gs: GameState): { idx: number; dist: number } | null {
  let best: { idx: number; dist: number } | null = null;
  for (let i = 0; i < gs.players.length; i++) {
    if (i === playerIdx || !gs.players[i].alive) continue;
    const d = Math.abs(gs.players[i].row - player.row) + Math.abs(gs.players[i].col - player.col);
    if (!best || d < best.dist) best = { idx: i, dist: d };
  }
  return best;
}

/** Count how many blocks a bomb at (r,c) would destroy */
function bombBlockValue(row: number, col: number, range: number, grid: number[][]): number {
  let count = 0;
  for (const [dr, dc] of DIRS) {
    for (let i = 1; i <= range; i++) {
      const nr = row + dr * i;
      const nc = col + dc * i;
      if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS || grid[nr][nc] === WALL) break;
      if (grid[nr][nc] === BLOCK) { count++; break; }
    }
  }
  return count;
}

/** Check if a bomb at (r,c) would threaten any enemy */
function bombThreatsEnemy(row: number, col: number, range: number, gs: GameState, selfIdx: number): boolean {
  for (const [dr, dc] of DIRS) {
    for (let i = 1; i <= range; i++) {
      const nr = row + dr * i;
      const nc = col + dc * i;
      if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS || gs.grid[nr][nc] === WALL) break;
      if (gs.grid[nr][nc] === BLOCK) break;
      for (let p = 0; p < gs.players.length; p++) {
        if (p !== selfIdx && gs.players[p].alive && gs.players[p].row === nr && gs.players[p].col === nc) return true;
      }
    }
  }
  return false;
}

/**
 * Try placing a bomb and find an escape route. Returns the escape direction or null if unsafe.
 * This is the KEY safety function — it simulates placing the bomb, calculates the new danger zone,
 * and BFS-finds a safe cell that's reachable. Returns the first step toward that safe cell.
 */
function tryBombAndEscape(
  player: Player, playerIdx: number, gs: GameState, ghost: boolean,
): Dir | null {
  if (player.activeBombs >= player.maxBombs) return null;
  if (gs.bombs.some((b) => !b.detonated && b.row === player.row && b.col === player.col)) return null;

  const hypothetical: Bomb[] = [...gs.bombs, {
    id: -1, row: player.row, col: player.col,
    owner: playerIdx, timer: BOMB_TIMER, range: player.range, detonated: false,
  }];
  const newDanger = getDangerCells(hypothetical, gs.grid);

  // BFS to find a safe cell reachable from the current position
  const bombCells = new Set(hypothetical.filter((b) => !b.detonated).map((b) => `${b.row},${b.col}`));
  const visited = new Set<string>();
  visited.add(`${player.row},${player.col}`);
  const queue: { r: number; c: number; firstDir: Dir }[] = [];

  for (const [dr, dc] of DIRS) {
    const nr = player.row + dr;
    const nc = player.col + dc;
    const key = `${nr},${nc}`;
    if (canPass(gs.grid, nr, nc, ghost) && !bombCells.has(key)) {
      const d = dirFromDelta(dr, dc);
      if (!newDanger.has(key)) return d; // immediate neighbor is safe — great escape
      visited.add(key);
      queue.push({ r: nr, c: nc, firstDir: d });
    }
  }

  while (queue.length > 0) {
    const { r, c, firstDir } = queue.shift()!;
    for (const [dr, dc] of DIRS) {
      const nr = r + dr;
      const nc = c + dc;
      const key = `${nr},${nc}`;
      if (!visited.has(key) && canPass(gs.grid, nr, nc, ghost) && !bombCells.has(key)) {
        if (!newDanger.has(key)) return firstDir; // found safe cell — return first step
        visited.add(key);
        queue.push({ r: nr, c: nc, firstDir });
      }
    }
  }

  return null; // no safe escape — don't bomb!
}

/** Safe BFS that avoids danger zones entirely */
function safeBfsFind(
  gs: GameState, danger: Set<string>,
  startR: number, startC: number,
  target: (r: number, c: number) => boolean,
  ghost: boolean,
): Dir | null {
  const visited = new Set<string>();
  visited.add(`${startR},${startC}`);
  const bombCells = new Set(gs.bombs.filter((b) => !b.detonated).map((b) => `${b.row},${b.col}`));
  const queue: { r: number; c: number; firstDir: Dir }[] = [];

  for (const [dr, dc] of DIRS) {
    const nr = startR + dr;
    const nc = startC + dc;
    const key = `${nr},${nc}`;
    if (canPass(gs.grid, nr, nc, ghost) && !bombCells.has(key) && !danger.has(key)) {
      const d = dirFromDelta(dr, dc);
      if (target(nr, nc)) return d;
      visited.add(key);
      queue.push({ r: nr, c: nc, firstDir: d });
    }
  }

  while (queue.length > 0) {
    const { r, c, firstDir } = queue.shift()!;
    for (const [dr, dc] of DIRS) {
      const nr = r + dr;
      const nc = c + dc;
      const key = `${nr},${nc}`;
      if (!visited.has(key) && canPass(gs.grid, nr, nc, ghost) && !bombCells.has(key) && !danger.has(key)) {
        if (target(nr, nc)) return firstDir;
        visited.add(key);
        queue.push({ r: nr, c: nc, firstDir });
      }
    }
  }
  return null;
}

function aiDecision(
  player: Player,
  playerIdx: number,
  gs: GameState,
): { move: Dir; placeBomb: boolean } {
  const danger = getDangerCells(gs.bombs, gs.grid);
  const inDanger = danger.has(`${player.row},${player.col}`);
  const ghost = player.ghost > 0;
  const hasBombSlot = player.activeBombs < player.maxBombs;
  const bombOnMe = gs.bombs.some((b) => !b.detonated && b.row === player.row && b.col === player.col);
  // Don't bomb if there are already bombs from us on the field — wait for them to explode first
  const myActiveBombs = gs.bombs.filter((b) => !b.detonated && b.owner === playerIdx).length;
  const canBomb = hasBombSlot && !bombOnMe && myActiveBombs === 0;

  // ─── Priority 1: Escape danger IMMEDIATELY ─────────────────────────
  if (inDanger) {
    const bombCells = new Set(gs.bombs.filter((b) => !b.detonated).map((b) => `${b.row},${b.col}`));
    const visited = new Set<string>();
    visited.add(`${player.row},${player.col}`);
    const queue: { r: number; c: number; firstDir: Dir }[] = [];

    for (const [dr, dc] of DIRS) {
      const nr = player.row + dr;
      const nc = player.col + dc;
      const key = `${nr},${nc}`;
      if (canPass(gs.grid, nr, nc, ghost) && !bombCells.has(key)) {
        const d = dirFromDelta(dr, dc);
        if (!danger.has(key)) return { move: d, placeBomb: false };
        visited.add(key);
        queue.push({ r: nr, c: nc, firstDir: d });
      }
    }
    while (queue.length > 0) {
      const { r, c, firstDir } = queue.shift()!;
      for (const [dr, dc] of DIRS) {
        const nr = r + dr;
        const nc = c + dc;
        const key = `${nr},${nc}`;
        if (!visited.has(key) && canPass(gs.grid, nr, nc, ghost) && !bombCells.has(key)) {
          if (!danger.has(key)) return { move: firstDir, placeBomb: false };
          visited.add(key);
          queue.push({ r: nr, c: nc, firstDir });
        }
      }
    }
    for (const [dr, dc] of DIRS) {
      const nr = player.row + dr;
      const nc = player.col + dc;
      if (canPass(gs.grid, nr, nc, ghost)) {
        return { move: dirFromDelta(dr, dc), placeBomb: false };
      }
    }
    return { move: null, placeBomb: false };
  }

  // ─── Priority 1.5: Preemptive — move away if adjacent to a bomb ────
  // Even if our cell isn't in the blast, if a neighbor cell has a bomb,
  // move away from it as a precaution
  const nearbyBomb = gs.bombs.find((b) => !b.detonated && b.owner !== playerIdx &&
    Math.abs(b.row - player.row) + Math.abs(b.col - player.col) <= 1);
  if (nearbyBomb) {
    const awayDir = safeBfsFind(gs, danger, player.row, player.col,
      (r, c) => !danger.has(`${r},${c}`) && Math.abs(r - nearbyBomb.row) + Math.abs(c - nearbyBomb.col) > 2, ghost);
    if (awayDir) return { move: awayDir, placeBomb: false };
  }

  // ─── Priority 2: Collect nearby power-ups ──────────────────────────
  const puDir = safeBfsFind(gs, danger, player.row, player.col, (r, c) =>
    gs.powerUps.some((p) => p.row === r && p.col === c), ghost);
  if (puDir) return { move: puDir, placeBomb: false };

  // ─── Priority 3: Personality-driven combat ─────────────────────────

  const enemy = findNearestEnemy(player, playerIdx, gs);

  if (player.personality === 'aggressive' && enemy) {
    const target = gs.players[enemy.idx];

    // Close to enemy — try to trap them (but only if we have no active bombs)
    if (enemy.dist <= 2 && canBomb) {
      if (bombThreatsEnemy(player.row, player.col, player.range, gs, playerIdx)) {
        const escapeDir = tryBombAndEscape(player, playerIdx, gs, ghost);
        if (escapeDir) return { move: escapeDir, placeBomb: true };
      }
    }

    // Move toward enemy safely
    const toward = safeBfsFind(gs, danger, player.row, player.col,
      (r, c) => r === target.row && c === target.col, ghost);
    if (toward) return { move: toward, placeBomb: false };
  }

  if (player.personality === 'cautious' && enemy && enemy.dist <= 3) {
    const target = gs.players[enemy.idx];
    const awayDir = safeBfsFind(gs, danger, player.row, player.col,
      (r, c) => Math.abs(r - target.row) + Math.abs(c - target.col) > 5, ghost);
    if (awayDir) return { move: awayDir, placeBomb: false };
  }

  if (player.personality === 'chaotic' && enemy) {
    if (enemy.dist <= 3 && canBomb && Math.random() < 0.25) {
      const escapeDir = tryBombAndEscape(player, playerIdx, gs, ghost);
      if (escapeDir) return { move: escapeDir, placeBomb: true };
    }
    if (Math.random() < 0.5) {
      const target = gs.players[enemy.idx];
      const toward = safeBfsFind(gs, danger, player.row, player.col,
        (r, c) => r === target.row && c === target.col, ghost);
      if (toward) return { move: toward, placeBomb: false };
    }
  }

  // ─── Priority 4: Destroy blocks (conservative — one bomb at a time) ─

  if (canBomb) {
    const blockScore = bombBlockValue(player.row, player.col, player.range, gs.grid);
    if (blockScore >= 1) {
      const escapeDir = tryBombAndEscape(player, playerIdx, gs, ghost);
      if (escapeDir) return { move: escapeDir, placeBomb: true };
    }

    // Walk to a bombing position
    const bombSpotDir = safeBfsFind(gs, danger, player.row, player.col, (r, c) =>
      bombBlockValue(r, c, player.range, gs.grid) >= 1, ghost);
    if (bombSpotDir) return { move: bombSpotDir, placeBomb: false };
  }

  // ─── Priority 5: Hunt enemies when no blocks left ──────────────────

  if (enemy) {
    const target = gs.players[enemy.idx];
    if (enemy.dist <= 2 && canBomb) {
      const escapeDir = tryBombAndEscape(player, playerIdx, gs, ghost);
      if (escapeDir) return { move: escapeDir, placeBomb: true };
    }
    const toward = safeBfsFind(gs, danger, player.row, player.col,
      (r, c) => Math.abs(r - target.row) + Math.abs(c - target.col) <= 1, ghost);
    if (toward) return { move: toward, placeBomb: false };
  }

  // ─── Fallback: wander safely ───────────────────────────────────────
  const shuffled = [...DIRS].sort(() => Math.random() - 0.5);
  for (const [dr, dc] of shuffled) {
    const nr = player.row + dr;
    const nc = player.col + dc;
    if (canPass(gs.grid, nr, nc, ghost) && !danger.has(`${nr},${nc}`)
      && !gs.bombs.some((b) => !b.detonated && b.row === nr && b.col === nc)) {
      return { move: dirFromDelta(dr, dc), placeBomb: false };
    }
  }
  return { move: null, placeBomb: false };
}

// ─── Explosion propagation ──────────────────────────────────────────────────

function detonateChain(gs: GameState, bombId: number): void {
  const queue = [bombId];
  const processed = new Set<number>();

  while (queue.length > 0) {
    const id = queue.shift()!;
    if (processed.has(id)) continue;
    processed.add(id);

    const bomb = gs.bombs.find((b) => b.id === id);
    if (!bomb || bomb.detonated) continue;
    bomb.detonated = true;
    sfxExplosion();

    // Return bomb slot to owner
    const owner = gs.players[bomb.owner];
    if (owner) owner.activeBombs = Math.max(0, owner.activeBombs - 1);

    // Center explosion
    gs.explosions.push({ row: bomb.row, col: bomb.col, timer: EXPLOSION_DURATION });

    // Propagate in 4 directions
    for (const [dr, dc] of DIRS) {
      for (let i = 1; i <= bomb.range; i++) {
        const nr = bomb.row + dr * i;
        const nc = bomb.col + dc * i;
        if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS) break;
        if (gs.grid[nr][nc] === WALL) break;

        gs.explosions.push({ row: nr, col: nc, timer: EXPLOSION_DURATION });

        if (gs.grid[nr][nc] === BLOCK) {
          gs.grid[nr][nc] = EMPTY;
          gs.gridDirty = true;
          if (Math.random() < POWERUP_CHANCE) {
            gs.powerUps.push({ row: nr, col: nc, type: randomPowerUp() });
          }
          break; // explosion stops at first block
        }

        // Chain reaction
        const chainBomb = gs.bombs.find((b) => !b.detonated && b.row === nr && b.col === nc);
        if (chainBomb) queue.push(chainBomb.id);
      }
    }
  }

  // Remove detonated bombs
  gs.bombs = gs.bombs.filter((b) => !b.detonated);
}

