// ─── Main component ─────────────────────────────────────────────────────────

export function BombBrawl({ lang, canOnline = false }: BombBrawlProps) {
  const [phase, setPhase] = useState<Phase>('charselect');
  const [mode, setMode] = useState<GameMode>('solo');
  const [selectedChar, setSelectedChar] = useState(0);
  const [countdown, setCountdown] = useState(3);
  const [, setTick] = useState(0);

  const gameRef = useRef<GameState | null>(null);
  const inputRef = useRef<Dir>(null);
  const bombInputRef = useRef(false);
  const loopRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [cellSize, setCellSize] = useState(40);
  const crumblesRef = useRef<{ r: number; c: number; id: number }[]>([]);
  const crumbleIdRef = useRef(0);

  // Online multiplayer state
  const remoteInputsRef = useRef<Map<string, { dir: Dir; bomb: boolean }>>(new Map());
  const myPlayerIdxRef = useRef(0);
  const playerIdMapRef = useRef<Map<string, number>>(new Map()); // mpPlayerId → game player index
  const broadcastTickRef = useRef(0);
  const isOnline = mode === 'online';
  const phaseRef = useRef<Phase>(phase);
  phaseRef.current = phase;

  // ─── Multiplayer hook ───────────────────────────────────────────────

  const browserRef = useRef<{ updatePlayerCount: (n: number) => void }>({ updatePlayerCount: () => {} });

  const handleMPEvent = useCallback((event: MultiplayerEvent) => {
    const mpNow = mpRef.current;
    if (event.type === 'guest-joined') {
      const existing = mpNow.room?.players ?? [];
      const newPlayers = [...existing, { id: event.playerId, name: event.name, isHost: false }];
      mpNow.addPlayer({ id: event.playerId, name: event.name, isHost: false });
      browserRef.current.updatePlayerCount(newPlayers.length);
      // Host acknowledges with the complete player list so late joiners see everyone.
      mpNow.sendEvent({ type: 'host-ack', name: loadPlayerName(), playerId: mpNow.room?.playerId ?? '', players: newPlayers });
    } else if (event.type === 'host-ack') {
      mpNow.setPlayers(event.players);
    } else if (event.type === 'player-list') {
      mpNow.setPlayers(event.players);
    } else if (event.type === 'player-left') {
      if (event.playerId) mpNow.removePlayer(event.playerId);
      // If someone leaves mid-game, end the room for everyone — nobody wants to keep playing alone.
      const ph = phaseRef.current;
      if (ph === 'countdown' || ph === 'playing' || ph === 'gameover') {
        stopLoop();
        if (mpNow.room?.role === 'host') browserRef.current.updatePlayerCount(0);
        mpNow.leaveRoom();
        setPhase('charselect');
        setMode('solo');
      }
    } else if (event.type === 'game-state') {
      const p = event.payload;
      if (p.action === 'input') {
        // Host receives guest input
        const pid = p.playerId as string;
        remoteInputsRef.current.set(pid, { dir: p.dir as Dir, bomb: p.bomb as boolean });
      } else if (p.action === 'start') {
        // Guest receives game start
        const gs = p.gameState as GameState;
        gameRef.current = gs;
        myPlayerIdxRef.current = p.yourIndex as number;
        const idMap = p.playerIdMap as Record<string, number>;
        playerIdMapRef.current = new Map(Object.entries(idMap));
        setPhase('countdown');
        setCountdown(3);
        let c = 3;
        const iv = setInterval(() => {
          c--;
          if (c <= 0) {
            clearInterval(iv);
            setPhase('playing');
          } else {
            setCountdown(c);
          }
        }, 700);
      } else if (p.action === 'tick') {
        // Guest receives state update
        const gs = gameRef.current;
        if (!gs) return;
        const state = p.state as { players: Player[]; bombs: Bomb[]; explosions: Explosion[]; powerUps: PowerUp[]; grid?: number[][]; running: boolean; winner: number; elapsed: number };
        gs.players = state.players;
        gs.bombs = state.bombs;
        gs.explosions = state.explosions;
        gs.powerUps = state.powerUps;
        if (state.grid) gs.grid = state.grid;
        gs.running = state.running;
        gs.winner = state.winner;
        gs.elapsed = state.elapsed;
        setTick((tk) => tk + 1);
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const mp = useMultiplayer({ gameId: 'bombbrawl', playerName: loadPlayerName(), onEvent: handleMPEvent });
  const mpRef = useRef(mp);
  mpRef.current = mp;
  const browser = useRoomBrowser({ gameId: 'bombbrawl', enabled: phase === 'lobby' && mode === 'online' });
  browserRef.current = browser;
  const availableRooms = browser.rooms;

  // Responsive cell size — generous on iPad, comfortable on mobile
  useEffect(() => {
    function calc() {
      const pad = window.innerWidth >= 768 ? 48 : 24;
      const maxW = Math.min(window.innerWidth - pad, 780);
      const controlsH = window.innerWidth >= 1024 ? 80 : 180;
      const maxH = window.innerHeight - controlsH;
      const byW = Math.floor(maxW / COLS);
      const byH = Math.floor(maxH / ROWS);
      const maxCell = window.innerWidth >= 768 ? 60 : 48;
      setCellSize(Math.max(26, Math.min(maxCell, byW, byH)));
    }
    calc();
    window.addEventListener('resize', calc);
    return () => window.removeEventListener('resize', calc);
  }, []);

  const boardW = COLS * cellSize;
  const boardH = ROWS * cellSize;

  const accent = CHARACTERS[selectedChar].accent;

  // ─── Initialize game state ──────────────────────────────────────────

  const initGame = useCallback((onlinePlayers?: { id: string; paletteIdx: number }[]) => {
    const grid = generateGrid();
    const spawns: [number, number][] = [
      [0, 0], [0, COLS - 1], [ROWS - 1, 0], [ROWS - 1, COLS - 1],
    ];
    const personalities: Personality[] = ['aggressive', 'cautious', 'chaotic'];

    let players: Player[];
    if (onlinePlayers && onlinePlayers.length > 0) {
      // Online: real players fill slots, rest are bots
      const totalSlots = 4;
      players = [];
      for (let i = 0; i < totalSlots; i++) {
        const isRemote = i < onlinePlayers.length;
        const pal = isRemote ? onlinePlayers[i].paletteIdx : Math.floor(Math.random() * PALETTES.length);
        players.push({
          row: spawns[i][0], col: spawns[i][1],
          alive: true, maxBombs: 1, activeBombs: 0, range: 1,
          speed: BASE_MOVE_INTERVAL, ghost: 0, shield: false,
          paletteIdx: pal, dir: null,
          isBot: !isRemote,
          personality: isRemote ? 'aggressive' : personalities[(i - onlinePlayers.length) % 3],
          moveCooldown: 0, aiCooldown: 200 + Math.random() * 200,
          walking: false, flipX: false,
        });
      }
    } else {
      // Solo: player 0 is human, rest are bots
      const usedPalettes = new Set([CHARACTERS[selectedChar].palette]);
      players = spawns.map((pos, i) => {
        let pal: number;
        if (i === 0) {
          pal = CHARACTERS[selectedChar].palette;
        } else {
          do { pal = Math.floor(Math.random() * PALETTES.length); } while (usedPalettes.has(pal));
          usedPalettes.add(pal);
        }
        return {
          row: pos[0], col: pos[1], alive: true, maxBombs: 1, activeBombs: 0, range: 1,
          speed: BASE_MOVE_INTERVAL, ghost: 0, shield: false, paletteIdx: pal, dir: null,
          isBot: i !== 0, personality: i === 0 ? 'aggressive' : personalities[(i - 1) % 3],
          moveCooldown: 0, aiCooldown: 200 + Math.random() * 200, walking: false, flipX: false,
        };
      });
    }

    const gs: GameState = {
      grid, players, bombs: [], explosions: [], powerUps: [],
      running: true, winner: -1, bombIdCounter: 0, elapsed: 0,
    };
    gameRef.current = gs;
    crumblesRef.current = [];
    return gs;
  }, [selectedChar]);

  // ─── Place bomb ─────────────────────────────────────────────────────

  const placeBomb = useCallback((playerIdx: number) => {
    const gs = gameRef.current;
    if (!gs) return;
    const p = gs.players[playerIdx];
    if (!p.alive || p.activeBombs >= p.maxBombs) return;
    if (gs.bombs.some((b) => b.row === p.row && b.col === p.col)) return;
    p.activeBombs++;
    sfxBomb();
    gs.bombs.push({
      id: gs.bombIdCounter++, row: p.row, col: p.col,
      owner: playerIdx, timer: BOMB_TIMER, range: p.range, detonated: false,
    });
  }, []);

  // ─── Game loop (runs on host or solo) ───────────────────────────────

  const startLoop = useCallback(() => {
    if (loopRef.current) clearInterval(loopRef.current);
    const DT = 16;
    broadcastTickRef.current = 0;

    loopRef.current = setInterval(() => {
      const gs = gameRef.current;
      if (!gs || !gs.running) return;
      gs.elapsed += DT;

      for (let i = 0; i < gs.players.length; i++) {
        const p = gs.players[i];
        if (!p.alive) continue;

        if (p.ghost > 0) p.ghost = Math.max(0, p.ghost - DT);

        if (p.isBot) {
          p.aiCooldown -= DT;
          if (p.aiCooldown <= 0) {
            const decision = aiDecision(p, i, gs);
            p.dir = decision.move;
            if (decision.placeBomb) {
              placeBomb(i);
              p.moveCooldown = 0; // immediately escape after bombing
            }
            p.aiCooldown = p.personality === 'aggressive' ? 80 + Math.random() * 80
              : p.personality === 'chaotic' ? 100 + Math.random() * 120
              : 120 + Math.random() * 140;
          }
        } else if (i === myPlayerIdxRef.current) {
          // Local player
          p.dir = inputRef.current;
          if (bombInputRef.current) {
            placeBomb(i);
            bombInputRef.current = false;
          }
        } else if (isOnline) {
          // Remote player — find their input
          for (const [mpId, idx] of playerIdMapRef.current.entries()) {
            if (idx === i) {
              const ri = remoteInputsRef.current.get(mpId);
              if (ri) {
                p.dir = ri.dir;
                if (ri.bomb) { placeBomb(i); ri.bomb = false; }
              }
              break;
            }
          }
        }

        // Movement
        p.moveCooldown -= DT;
        if (p.moveCooldown <= 0 && p.dir) {
          const d = DIR_MAP[p.dir];
          if (d) {
            const nr = p.row + d[0];
            const nc = p.col + d[1];
            const ghost = p.ghost > 0;
            if (canPass(gs.grid, nr, nc, ghost) && !gs.bombs.some((b) => b.row === nr && b.col === nc)) {
              p.row = nr; p.col = nc;
              p.moveCooldown = p.speed; p.walking = true;
              p.flipX = d[1] < 0;
            }
          }
        }
        p.walking = p.moveCooldown > p.speed * 0.5;
      }

      for (const bomb of gs.bombs) {
        if (bomb.detonated) continue;
        bomb.timer -= DT;
        if (bomb.timer <= 0) detonateChain(gs, bomb.id);
      }

      gs.explosions = gs.explosions.filter((e) => { e.timer -= DT; return e.timer > 0; });

      const explosionSet = new Set(gs.explosions.map((e) => `${e.row},${e.col}`));
      for (const p of gs.players) {
        if (!p.alive) continue;
        if (explosionSet.has(`${p.row},${p.col}`)) {
          if (p.shield) p.shield = false;
          else { p.alive = false; sfxDeath(); }
        }
      }

      for (const p of gs.players) {
        if (!p.alive) continue;
        const puIdx = gs.powerUps.findIndex((pu) => pu.row === p.row && pu.col === p.col);
        if (puIdx !== -1) {
          const pu = gs.powerUps[puIdx];
          sfxPowerUp();
          switch (pu.type) {
            case 'fire': p.range = Math.min(6, p.range + 1); break;
            case 'bomb': p.maxBombs = Math.min(5, p.maxBombs + 1); break;
            case 'speed': p.speed = Math.max(100, p.speed - SPEED_BONUS); break;
            case 'ghost': p.ghost = GHOST_DURATION; break;
            case 'shield': p.shield = true; break;
          }
          gs.powerUps.splice(puIdx, 1);
        }
      }

      const alive = gs.players.filter((p) => p.alive);
      if (alive.length <= 1) {
        gs.running = false;
        gs.winner = alive.length === 1 ? gs.players.indexOf(alive[0]) : -1;
      }

      // Broadcast state to guests (every ~5 ticks = 80ms). Grid only when it actually changed.
      if (isOnline && mp.room?.role === 'host') {
        broadcastTickRef.current++;
        if (broadcastTickRef.current % 5 === 0 || !gs.running) {
          const state: Record<string, unknown> = {
            players: gs.players, bombs: gs.bombs, explosions: gs.explosions,
            powerUps: gs.powerUps, running: gs.running,
            winner: gs.winner, elapsed: gs.elapsed,
          };
          if (gs.gridDirty || !gs.running) {
            state.grid = gs.grid;
            gs.gridDirty = false;
          }
          mp.sendEvent({ type: 'game-state', payload: { action: 'tick', state } });
        }
      }

      setTick((tk) => tk + 1);
    }, DT);
  }, [placeBomb, isOnline, mp]);

  const stopLoop = useCallback(() => {
    if (loopRef.current) { clearInterval(loopRef.current); loopRef.current = null; }
  }, []);

  // ─── Guest: send input to host on change ────────────────────────────

  const lastSentInput = useRef<{ dir: Dir; bomb: boolean }>({ dir: null, bomb: false });

  useEffect(() => {
    if (!isOnline || mpRef.current.room?.role !== 'guest' || phase !== 'playing') return;
    const iv = setInterval(() => {
      const room = mpRef.current.room;
      if (!room) return;
      const dir = inputRef.current;
      const bomb = bombInputRef.current;
      if (dir !== lastSentInput.current.dir || bomb) {
        lastSentInput.current = { dir, bomb };
        mpRef.current.sendEvent({
          type: 'game-state',
          payload: { action: 'input', playerId: room.playerId, dir, bomb },
        });
        if (bomb) bombInputRef.current = false;
      }
    }, 50);
    return () => clearInterval(iv);
  }, [isOnline, phase]);

  // ─── Keyboard input ─────────────────────────────────────────────────

  useEffect(() => {
    if (phase !== 'playing') return;
    const keyDir: Record<string, Dir> = {
      ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
      w: 'up', s: 'down', a: 'left', d: 'right',
      W: 'up', S: 'down', A: 'left', D: 'right',
    };
    const held = new Set<string>();

    function onDown(e: KeyboardEvent) {
      if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); bombInputRef.current = true; return; }
      const dir = keyDir[e.key];
      if (dir) { e.preventDefault(); held.add(e.key); inputRef.current = dir; }
    }
    function onUp(e: KeyboardEvent) {
      held.delete(e.key);
      if (held.size === 0) inputRef.current = null;
      else { const last = [...held].pop()!; inputRef.current = keyDir[last] ?? null; }
    }

    window.addEventListener('keydown', onDown);
    window.addEventListener('keyup', onUp);
    return () => { window.removeEventListener('keydown', onDown); window.removeEventListener('keyup', onUp); };
  }, [phase]);

  // ─── Start game (solo) ──────────────────────────────────────────────

  const startSoloGame = useCallback(() => {
    audioEnabled = true;
    initGame();
    myPlayerIdxRef.current = 0;
    setPhase('countdown');
    setCountdown(3);
    sfxCountdown();
    let c = 3;
    const iv = setInterval(() => {
      c--;
      if (c <= 0) { clearInterval(iv); setPhase('playing'); startLoop(); sfxGo(); }
      else { setCountdown(c); sfxCountdown(); }
    }, 700);
  }, [initGame, startLoop]);

  // ─── Start online match (host only) ─────────────────────────────────

  const startOnlineMatch = useCallback(() => {
    if (!mp.room || mp.room.role !== 'host') return;
    audioEnabled = true;
    browser.unpublishRoom(); // Remove from browser — game is starting
    const roomPlayers = mp.room.players;
    // Build online player list with palette assignments
    const onlinePlayers = roomPlayers.map((p, i) => ({
      id: p.id,
      paletteIdx: CHARACTERS[i % CHARACTERS.length].palette,
    }));
    const gs = initGame(onlinePlayers);
    myPlayerIdxRef.current = 0;

    // Build player ID map
    const idMap: Record<string, number> = {};
    roomPlayers.forEach((p, i) => { idMap[p.id] = i; });
    playerIdMapRef.current = new Map(Object.entries(idMap));

    // Broadcast game start to all guests
    mp.sendEvent({
      type: 'game-state',
      payload: {
        action: 'start',
        gameState: gs,
        playerIdMap: idMap,
        // Each guest needs to know their index
      },
    });

    // Also send individual index to each guest
    roomPlayers.forEach((p, i) => {
      if (!p.isHost) {
        mp.sendEvent({
          type: 'game-state',
          payload: { action: 'start', gameState: gs, yourIndex: i, playerIdMap: idMap },
        });
      }
    });

    setPhase('countdown');
    setCountdown(3);
    let c = 3;
    const iv = setInterval(() => {
      c--;
      if (c <= 0) { clearInterval(iv); setPhase('playing'); startLoop(); }
      else setCountdown(c);
    }, 700);
  }, [mp, initGame, startLoop]);

  // Cleanup
  useEffect(() => {
    return () => { stopLoop(); killAudio(); if (isOnline) { browser.unpublishRoom(); mp.leaveRoom(); } };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stopLoop]);

  // ─── Read game state for rendering ─────────────────────────────────

  const gs = gameRef.current;

  const { walls, blocks } = useMemo(() => {
    if (!gs) return { walls: [] as [number, number][], blocks: [] as [number, number][] };
    const w: [number, number][] = [];
    const b: [number, number][] = [];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (gs.grid[r][c] === WALL) w.push([r, c]);
        else if (gs.grid[r][c] === BLOCK) b.push([r, c]);
      }
    }
    return { walls: w, blocks: b };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gs, gs?.elapsed]);

  // ─── Render: character select ───────────────────────────────────────

  if (phase === 'charselect') {
    return (
      <Wrapper>
        <Title>💣 BombBrawl</Title>
        <Subtitle>{t('subtitle', lang)}</Subtitle>
        {canOnline && (
          <ModeToggle>
            <ModeBtn active={mode === 'solo'} color="#f59e0b" onClick={() => setMode('solo')}>
              🎯 {t('solo', lang)}
            </ModeBtn>
            <ModeBtn active={mode === 'online'} color="#3fb950" onClick={() => setMode('online')}>
              🌐 {t('online', lang)}
            </ModeBtn>
          </ModeToggle>
        )}
        <CharGrid>
          {CHARACTERS.map((ch, i) => (
            <CharCard
              key={i}
              accent={ch.accent}
              selected={selectedChar === i}
              onClick={() => setSelectedChar(i)}
            >
              <PixelCharacter paletteIndex={ch.palette} pose="idle" size={cellSize * 1.2} />
              <CharName accent={ch.accent}>{ch.name[lang === 'pt' ? 'pt' : 'en']}</CharName>
              <CharDesc>{ch.desc[lang === 'pt' ? 'pt' : 'en']}</CharDesc>
            </CharCard>
          ))}
        </CharGrid>
        <StartBtn accent={accent} onClick={isOnline ? () => setPhase('lobby') : startSoloGame}>
          {isOnline ? t('online', lang) : t('start', lang)}
        </StartBtn>
        <ControlsHint>
          {typeof window !== 'undefined' && 'ontouchstart' in window
            ? t('controlsMobile', lang)
            : t('controls', lang)}
        </ControlsHint>
      </Wrapper>
    );
  }

  // ─── Render: lobby (online) ─────────────────────────────────────────

  if (phase === 'lobby') {
    const isHost = mp.room?.role === 'host';
    const playerCount = mp.room?.players.length ?? 0;
    const canStart = isHost && playerCount >= 2;

    return (
      <Wrapper>
        <Title>💣 BombBrawl</Title>
        {mp.room?.connected ? (
          <LobbyWrap>
            <Subtitle>👥 {playerCount}/4 {lang === 'pt' ? 'jogadores' : 'players'}</Subtitle>
            <LobbyCharRow>
              {mp.room.players.map((p, i) => (
                <CharCard key={p.id} accent={CHARACTERS[i % CHARACTERS.length].accent} selected={false}>
                  <PixelCharacter paletteIndex={CHARACTERS[i % CHARACTERS.length].palette} pose="idle" size={52} />
                  <CharName accent={CHARACTERS[i % CHARACTERS.length].accent}>{p.name}</CharName>
                  {p.isHost && <CharDesc>👑 Host</CharDesc>}
                </CharCard>
              ))}
            </LobbyCharRow>
            {canStart && (
              <LobbyStartBtn accent="#3fb950" onClick={startOnlineMatch}>
                {t('startMatch', lang)}
              </LobbyStartBtn>
            )}
            {!isHost && <Subtitle>{t('waiting', lang)}</Subtitle>}
          </LobbyWrap>
        ) : (
          <MultiplayerLobby
            lang={lang}
            room={mp.room}
            error={mp.error}
            onCreateRoom={(name) => {
              const { code, roomName } = mp.createRoom();
              browser.publishRoom({ code, roomName, hostName: name, playerCount: 1 });
            }}
            onJoinRoom={(code, name) => mp.joinRoom(code)}
            onLeaveRoom={() => { browser.unpublishRoom(); mp.leaveRoom(); setPhase('charselect'); }}
            availableRooms={availableRooms}
          />
        )}
      </Wrapper>
    );
  }

  // ─── Render: game over ──────────────────────────────────────────────

  if (phase === 'playing' && gs && !gs.running) {
    const myIdx = myPlayerIdxRef.current;
    const win = gs.winner === myIdx;
    const isDraw = gs.winner === -1;
    const winnerPalette = gs.winner >= 0 ? gs.players[gs.winner].paletteIdx : selectedChar;

    return (
      <Wrapper>
        <GameOverWrap>
          <WinnerChar>
            <PixelCharacter paletteIndex={winnerPalette} pose={isDraw ? 'dead' : 'jump'} size={120} />
          </WinnerChar>
          <GameOverTitle win={win}>
            {isDraw ? t('draw', lang) : win ? t('youWin', lang) : t('youLose', lang)}
          </GameOverTitle>
          <StartBtn
            accent={win ? '#3fb950' : '#f97583'}
            onClick={() => {
              stopLoop();
              if (isOnline) { browser.unpublishRoom(); mp.leaveRoom(); }
              setPhase('charselect');
            }}
          >
            {t('playAgain', lang)}
          </StartBtn>
        </GameOverWrap>
      </Wrapper>
    );
  }

  // ─── Render: countdown + playing ────────────────────────────────────

  if (!gs) return <Wrapper />;

  const myIdx = myPlayerIdxRef.current;
  const human = gs.players[myIdx] ?? gs.players[0];

  return (
    <Wrapper>
      <GameArea ref={containerRef}>
        {/* HUD */}
        <HUD>
          <PixelCharacter paletteIndex={human.paletteIdx} pose="idle" size={28} />
          <HUDItem>💣 <HUDValue color="#ff4444">{human.maxBombs - human.activeBombs}/{human.maxBombs}</HUDValue></HUDItem>
          <HUDItem>🔥 <HUDValue color="#ff8844">{human.range}</HUDValue></HUDItem>
          <HUDItem>🏃 <HUDValue color="#44ff44">{Math.round((1 - (human.speed - 100) / (BASE_MOVE_INTERVAL - 100)) * 100)}%</HUDValue></HUDItem>
          {human.shield && <HUDItem>🛡️</HUDItem>}
          {human.ghost > 0 && <HUDItem>👻 <HUDValue color="#aa88ff">{Math.ceil(human.ghost / 1000)}s</HUDValue></HUDItem>}
        </HUD>

        {/* Board */}
        <BoardContainer w={boardW} h={boardH}>
          <FloorLayer cellSize={cellSize} />

          {walls.map(([r, c]) => (
            <WallCell key={`w${r},${c}`} r={r} c={c} size={cellSize} />
          ))}

          {blocks.map(([r, c]) => (
            <BlockCell key={`b${r},${c}`} r={r} c={c} size={cellSize} />
          ))}

          {gs.powerUps.map((pu, i) => (
            <PowerUpDiv key={`pu${pu.row},${pu.col}-${i}`} r={pu.row} c={pu.col} size={cellSize}>
              <PowerUpIcon glowColor={POWERUP_GLOW[pu.type]}>
                {POWERUP_EMOJI[pu.type]}
              </PowerUpIcon>
            </PowerUpDiv>
          ))}

          {gs.bombs.map((b) => (
            <BombDiv key={`bomb${b.id}`} r={b.row} c={b.col} size={cellSize}>
              <span className="bomb-inner" style={{ fontSize: Math.max(16, cellSize * 0.6) }}>💣</span>
            </BombDiv>
          ))}

          {gs.explosions.map((e, i) => (
            <ExplosionDiv
              key={`exp${e.row},${e.col}-${i}`}
              r={e.row} c={e.col} size={cellSize}
              center={e.timer > EXPLOSION_DURATION - 50}
            />
          ))}

          {gs.players.map((p, i) => (
            <PlayerDiv
              key={`p${i}`}
              r={p.row} c={p.col} size={cellSize}
              alive={p.alive}
              ghostActive={p.ghost > 0}
              shieldActive={p.shield}
            >
              {p.isBot && p.alive && (
                <PlayerTag color={CHARACTERS[p.paletteIdx % CHARACTERS.length]?.accent ?? '#888'}>
                  {p.personality === 'aggressive' ? '😈' : p.personality === 'cautious' ? '🤓' : '🤪'}
                </PlayerTag>
              )}
              <PixelCharacter
                paletteIndex={p.paletteIdx}
                pose={!p.alive ? 'dead' : p.walking ? 'walk' : 'idle'}
                size={Math.round(cellSize * 0.85)}
                flipX={p.flipX}
              />
            </PlayerDiv>
          ))}

          {phase === 'countdown' && (
            <CountdownOverlay>
              <CountdownText key={countdown} accent={accent}>
                {countdown === 0 ? t('go', lang) : countdown}
              </CountdownText>
            </CountdownOverlay>
          )}
        </BoardContainer>

        {phase === 'playing' && (
          <TouchControls
            onMove={(s: TouchMoveState) => {
              let dir: Dir = null;
              if (Math.abs(s.dx) > Math.abs(s.dy)) {
                if (s.dx === 1) dir = 'right';
                else if (s.dx === -1) dir = 'left';
              } else {
                if (s.dy === 1) dir = 'down';
                else if (s.dy === -1) dir = 'up';
              }
              inputRef.current = dir;
            }}
            actions={[
              {
                id: 'bomb',
                label: '💣',
                color: '#dc2626',
                onPress: () => { bombInputRef.current = true; },
              },
            ]}
          />
        )}
      </GameArea>
    </Wrapper>
  );
}
